{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'nav', 'Class' => ui_s(ui_cnv(['mx-auto w-full max-w-md border-t border-border', (ui_t(ui_eq($v_tone, 'muted')) ? 'bg-muted' : 'bg-background'), (ui_t(ui_eq($v_position, 'sticky')) ? 'sticky bottom-0 z-40' : '')])), 'Attrs' => ui_attrs(['aria-label', ui_coalesce([$v_landmarkLabel, $v_label]), 'data-testid', 'bottom-nav', 'data-position', $v_position])], 'children' => $c_5])|noescape}
